export const resources: Record<Locale, Record<string, string>> = Object.fromEntries(languages.map(([code]) => [code, { ...en, ...localized[code] }])) as Record<Locale, Record<string, string>>;
export const invariantEnglish = new Set<string>(['USDT', 'VRF', 'Chainlink']);
export function catalogAudit() {
  const keys = Object.keys(en);
  const placeholders = (value: string) => [...value.matchAll(/\{\{\s*([^} ]+)\s*\}\}/g)].map((match) => match[1]).sort().join('|');
  const byLocale = languages.map(([locale]) => {
    const catalog = resources[locale];
    const translatedCatalog = locale === 'en' ? en : (localized[locale] ?? {});
    const missing = keys.filter((key) => !(key in catalog));
    const empty = keys.filter((key) => !catalog[key]?.trim());
    const placeholderMismatches = keys.filter((key) => placeholders(catalog[key] ?? '') !== placeholders(en[key]));
    const translationMissing = keys.filter((key) => !(key in translatedCatalog));
    const translationEmpty = keys.filter((key) => !translatedCatalog[key]?.trim());
    const translationPlaceholderMismatches = keys.filter((key) => key in translatedCatalog && placeholders(translatedCatalog[key] ?? '') !== placeholders(en[key]));
    const identical = locale === 'en' ? [] : keys.filter((key) => catalog[key] === en[key] && !invariantEnglish.has(catalog[key]));
    return { locale, missing, empty, placeholderMismatches, translationMissing, translationEmpty, translationPlaceholderMismatches, identical };
  });
  return { keys: keys.length, byLocale };
}
type I18n = { locale: Locale; setLocale:(locale:Locale)=>void; t:(key:string)=>string; number:(value:number|bigint, options?:Intl.NumberFormatOptions)=>string; date:(value:Date|number, options?:Intl.DateTimeFormatOptions)=>string };
const Context = createContext<I18n | undefined>(undefined);
export function I18nProvider({children}:{children:ReactNode}) { const [locale,setLocale] = useState<Locale>(()=>resolveLocale(localStorage.getItem(storageKey) ?? navigator.language)); useEffect(()=>{ localStorage.setItem(storageKey,locale); document.documentElement.lang=locale; },[locale]); const value=useMemo<I18n>(()=>({locale,setLocale,t:(key)=>resources[locale][key] ?? en[key] ?? key,number:(v,o)=>new Intl.NumberFormat(locale,o).format(v),date:(v,o)=>new Intl.DateTimeFormat(locale,o).format(v)}),[locale]); return <Context.Provider value={value}>{children}</Context.Provider>; }
export function useI18n(){ const value=useContext(Context); if(!value) throw new Error('I18nProvider is required'); return value; }
